// Packages:
// - ModelContextProtocol --version 1.*
// - Microsoft.Extensions.DependencyInjection
// - Microsoft.Extensions.Logging

using Microsoft.Extensions.Logging;
using ModelContextProtocol;
using ModelContextProtocol.Server;

// Sample repository and model for demonstration
public record Order(string PublicId, string Status, DateTime EstimatedDelivery, List<string>? TrackingNumbers = null);

public interface IOrderRepository
{
    Task<Order?> GetByPublicIdAsync(string publicId, CancellationToken ct);
}

public sealed class GetOrderStatusTool
{
    private readonly IOrderRepository _orders;
    private readonly ILogger<GetOrderStatusTool> _logger;

    // Constructor injection for dependencies
    public GetOrderStatusTool(IOrderRepository orders, ILogger<GetOrderStatusTool> logger)
    {
        _orders = orders;
        _logger = logger;
    }

    [McpServerTool(Name = "get_order_status")]
    public async Task<string> ExecuteAsync(
        string orderId,
        bool includeTracking = false,
        CancellationToken ct = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(orderId);

        _logger.LogInformation("Fetching order {OrderId}", orderId);

        // Sample data: repository returns an Order like this
        // Order(PublicId: "ORD-1042", Status: "Shipped", EstimatedDelivery: 2024-12-15)
        var order = await _orders.GetByPublicIdAsync(orderId, ct);
        if (order is null)
            throw new InvalidOperationException($"Order '{orderId}' not found.");

        var payload = new
        {
            order.Status,
            order.EstimatedDelivery,
            Tracking = includeTracking ? order.TrackingNumbers : null
        };

        var json = JsonSerializer.Serialize(payload);

        // Expected JSON output:
        // {
        //   "status": "Shipped",
        //   "estimatedDelivery": "2024-12-15T00:00:00",
        //   "tracking": ["1Z999AA10123456784"]
        // }
        return json;
    }
}

